static boolean contains(long[] ids, long target) {
    for (long id : ids) if (id == target) return true;
    return false; // O(n) time, O(1) extra space
}

static int binarySearch(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) left = mid + 1; else right = mid - 1;
    }
    return -1;
}

static boolean hasPairWithSum(int[] values, int target) {
    int left = 0, right = values.length - 1;
    while (left < right) {
        int sum = values[left] + values[right];
        if (sum == target) return true;
        if (sum < target) left++; else right--;
    }
    return false;
}

static int longestUnique(String value) {
    Map<Character, Integer> last = new HashMap<>(); int left = 0, best = 0;
    for (int right = 0; right < value.length(); right++) {
        Integer seen = last.put(value.charAt(right), right);
        if (seen != null) left = Math.max(left, seen + 1);
        best = Math.max(best, right - left + 1);
    }
    return best;
}

static int maxDepth(Node node) {
    if (node == null) return 0;
    return 1 + Math.max(maxDepth(node.left), maxDepth(node.right));
}
record Node(int value, Node left, Node right) {}

static int minCost(int[] cost) {
    int prev2 = 0, prev1 = 0;
    for (int i = 2; i <= cost.length; i++) {
        int current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1; prev1 = current;
    }
    return prev1;
}

static int removeValue(int[] values, int target) {
    int write = 0;
    for (int value : values) if (value != target) values[write++] = value;
    return write; // new logical length, O(n)
}

static Node reverse(Node head) {
    Node previous = null;
    while (head != null) { Node next = head.next; head.next = previous; previous = head; head = next; }
    return previous;
}
static final class Node { int value; Node next; Node(int value) { this.value = value; } }

static boolean balanced(String text) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char ch : text.toCharArray()) {
        if (ch == '(') stack.push(ch);
        else if (ch == ')' && (stack.isEmpty() || stack.pop() != '(')) return false;
    }
    return stack.isEmpty();
}

