static int count(Node node) {
    return node == null ? 0 : 1 + count(node.left) + count(node.right);
}
record Node(int value, Node left, Node right) {}

static boolean contains(Node node, int target) {
    while (node != null) {
        if (node.value == target) return true;
        node = target < node.value ? node.left : node.right;
    }
    return false;
}
static final class Node { int value; Node left, right; }

static List<Integer> inorder(Node node, List<Integer> out) {
    if (node == null) return out;
    inorder(node.left, out); out.add(node.value); inorder(node.right, out);
    return out;
}
record Node(int value, Node left, Node right) {}

PriorityQueue<Integer> minHeap = new PriorityQueue<>();
for (int value : values) { minHeap.offer(value); }
int smallest = minHeap.poll(); // O(log n)

static void bfs(Map<Integer, List<Integer>> graph, int start) {
    Queue<Integer> queue = new ArrayDeque<>(); Set<Integer> seen = new HashSet<>();
    queue.offer(start); seen.add(start);
    while (!queue.isEmpty()) for (int next : graph.getOrDefault(queue.poll(), List.of()))
        if (seen.add(next)) queue.offer(next);
}

