static long sum(long[] values) {
    long total = 0;
    for (long value : values) total += value;
    return total; // a hot loop is a typical JIT optimization candidate
}

static final List<Runnable> listeners = new ArrayList<>();
static void register(Runnable listener) { listeners.add(listener); }
