final class Inventory {
  private int available;
  boolean reserve(int quantity) { if (quantity <= 0 || quantity > available) return false; available -= quantity; return true; }
}

interface PaymentProcessor { Receipt charge(Order order); }
final class CheckoutService {
  private final PaymentProcessor processor;
  CheckoutService(PaymentProcessor processor) { this.processor = processor; }
  Receipt checkout(Order order) { return processor.charge(order); }
}

final class OrderService {
  private final TaxCalculator taxes;
  OrderService(TaxCalculator taxes) { this.taxes = taxes; }
  Money total(Order order) { return order.subtotal().add(taxes.calculate(order)); }
}

