public Product getProduct(String sku) {
    String key = "product:" + sku;
    Product cached = redis.opsForValue().get(key);
    if (cached != null) return cached;
    Product product = productRepo.findBySku(sku)
        .orElseThrow(() -> new NotFoundException(sku));
    redis.opsForValue().set(key, product, Duration.ofMinutes(15));
    return product;
}

@Cacheable(value = "products", key = "#sku", unless = "#result == null")
@CacheEvict(value = "products", key = "#product.sku")
public Product updateProduct(Product product) { return productRepo.save(product); }

